import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    try:
        n = int(data[0])
    except:
        return
    if n <= 0:
        result = 0
    else:
        result = n * (n + 1) // 2
    sys.stdout.write(str(result))

if __name__ == "__main__":
    solve()
